#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long b;
    cin >> n >> b;
    vector<int> a(n);
    vector<int> c(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        c[i] = (a[i] % 2 == 0) ? 1 : -1;
    }
    long long sum = 0;
    vector<int> diffs;
    for (int i = 0; i < n - 1; i++) {
        sum += c[i];
        if (sum == 0) {
            diffs.push_back(abs(a[i] - a[i + 1]));
        }
    }
    sort(diffs.begin(), diffs.end());
    long long total = 0;
    int count = 0;
    for (int d : diffs) {
        total += d;
        if (total <= b) {
            count++;
        } else {
            break;
        }
    }
    cout << count << "\n";
    return 0;
}
